/* @socom-skeleton stub ExtendPath__7CAiMapsFR7CAiPathRC9CAiMapLoc */
bool CAiMaps::ExtendPath(CAiPath &path, const CAiMapLoc &goal)
{
	/* 0x199220 (FollowTick): move a path's goal end on to a new goal on the same map: a
	 * straight walkable line from the old goal appends the new one; else a path following a
	 * template (flag 8: the master's snake trail) takes the template's points between the
	 * two, then the goal (both smoothed, turn angles updated). True when extended. */
	if (path.m_points.size() == 0)
		return false;

	CAiMapLoc end = path.m_points[0].m_loc; /* the goal end (points are stored goal first) */

	if (end.m_mapid != goal.m_mapid)
		return false;

	if (end.x == goal.x && end.y == goal.y)
		return true;

	CAiMap* map = GetMapByIndex(end.m_mapid);

	if (map != NULL && map->CanTravelLine(end, goal, NULL))
	{
		path.AppendPathLoc(goal, NULL);

		if (path.m_flags & 1)
			path.SmoothPath();

		path.IncrementPathId();
		return true;
	}

	CAiPath* tmpl = path.m_template;

	if (!(path.m_flags & 8) || tmpl == NULL)
		return false;

	bool extended = false;
	unsigned int from, to;

	if (tmpl->PointInPath(end, &from))
	{
		if (tmpl->PointInPath(goal, &to))
		{
			int step = to < from ? -1 : 1;

			for (unsigned int i = from; i != to; i += step)
			{
				CAiPath::point &p = tmpl->m_points[tmpl->m_points.size() - i - 1];
				path.AppendPathLoc(p.m_loc, GetMapByIndex(p.m_loc.m_mapid));
			}

			path.AppendPathLoc(goal, GetMapByIndex(goal.m_mapid));
			extended = true;
		}
	}

	path.SmoothPath();
	path.UpdateTurnAngles();
	return extended;
}

/* @socom-skeleton body UpdateActionTables__7CAiMapsFv */
void CAiMaps::UpdateActionTables()
{
	/* 0x199010: per map (index = map id): every action's id is reset to invalid and its ex
	 * locations take the map id; every region takes the map id and, for types 0-6, is listed
	 * in m_regions[type] */
	u32 index = 0;

	for (iterator m = begin(); m != end(); ++m, index++)
	{
		CAiMap* map = (CAiMap*)*m;

		for (CAiMap::actions::iterator a = map->m_actionTable.begin(); a != map->m_actionTable.end(); ++a)
		{
			a->m_actionId = CAiMap::action::invalid[0];

			if (a->m_locExValid)
			{
				for (int i = 0; i < 6; i++)
					a->m_locEx[i].m_mapid = index;
			}
		}

		for (CAiMap::regions::iterator r = map->m_regionTable.begin(); r != map->m_regionTable.end(); ++r)
		{
			r->m_loc.m_mapid = index;
			u32 type = r->m_type;

			if (type < 7)
				m_regions[type].push_back(r->m_loc);
		}
	}
}

/* @socom-skeleton body UpdateNameTables__7CAiMapsFv */
void CAiMaps::UpdateNameTables()
{
	/* 0x198d10: m_names[type] (types 1-5; 0 is unused) collects every map's names of that
	 * type, their map id set to the map's index, sorted by name */
	for (int type = 1; type < 6; type++)
	{
		CAiMap::names &table = m_names[type];
		table.clear();
		int count = 0;

		for (iterator m = begin(); m != end(); ++m)
		{
			CAiMap* map = (CAiMap*)*m;

			for (CAiMap::names::iterator n = map->m_namesTable.begin(); n != map->m_namesTable.end(); ++n)
			{
				if (n->m_type == type)
					count++;
			}
		}

		if (count > 0)
		{
			table.reserve(count);
			u32 index = 0;

			for (iterator m = begin(); m != end(); ++m, index++)
			{
				CAiMap* map = (CAiMap*)*m;

				for (CAiMap::names::iterator n = map->m_namesTable.begin(); n != map->m_namesTable.end(); ++n)
				{
					if (n->m_type == type)
					{
						CAiMap::name copy = *n;
						copy.m_loc.m_mapid = index;
						table.push_back(copy);
					}
				}
			}
		}

		table.SortByNames();
	}
}

